b.com/greed-216/histree/blob/4a35069cfc3928f34adb41bee7eced8805e1e876/content/books/zizhi-tongjian/vol-281/year-0938/part-02/sources/library/tongjian-281-938-palace-and-policy/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003345；电子底本待考，分段待核", "id": "b8b407fc-5dfa-5848-a5fd-0f3b8a85b221"}]'::jsonb)
