INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "述律平", "aliases": ["述律氏", "述律后", "述律皇后"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：述律平。", "biography": null, "status": "draft", "id": "1c865dcb-3259-50e9-b13e-181615308183"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "刘昫", "aliases": ["劉昫", "刘煦", "劉煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘昫，端明殿学士、受相职者。", "biography": null, "status": "draft", "id": "b63eeed9-ecc3-575d-aba8-41b03e6caa3e"}, {"name": "韦勋（后晋册礼使）", "aliases": ["韦勋", "韋勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋使臣。《辽史》记载，938年十一月壬子与冯道一起为契丹皇太后册上尊号。《旧五代史》所载使团安排不同，另保留引用。", "biography": null, "status": "draft", "id": "660388c7-b6e3-568d-a11d-3ed17b14eaea"}, {"name": "卢重（后晋给事中）", "aliases": ["卢重", "盧重"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋给事中。《辽史》记载，938年十一月丙寅与刘昫一起为契丹皇帝册上尊号。《旧五代史》所载使团安排不同，另保留引用。", "biography": null, "status": "draft", "id": "af703ace-e770-5088-a4c8-2065cc15192d"}, {"name": "韩延徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷269贞明二年条所见人物：韩延徽。", "biography": null, "status": "draft", "id": "0ca1edb4-4ddc-5483-b6ab-1513e30cf800"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "赵思温", "aliases": ["趙思溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：赵思温，平州人、拒行回应者。", "biography": null, "status": "draft", "id": "6d48dbcb-e174-55d5-895a-98e065e6f82c"}, {"name": "赵延照", "aliases": ["趙延照"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵思温的儿子。《资治通鉴》记载，他在后晋任祁州刺史，并受父亲委托向石敬瑭转达幽州归附的请求。相关行动的具体年份未载。", "biography": null, "status": "draft", "id": "a3905a7c-cc29-5e76-a63f-eede596759ff"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "朱宪（后晋内职官）", "aliases": ["朱宪", "硃宪", "硃憲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内职官，汴州人。938年被石敬瑭派往广晋城，劝范延光归降。生卒年未载。", "biography": null, "status": "draft", "id": "2e2c6d39-fe87-5709-9351-40e800a7336c"}, {"name": "李式（范延光节度副使）", "aliases": ["李式"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的节度副使。938年范延光在考虑归降时，向他表示相信石敬瑭不杀自己的承诺。生卒年未载。", "biography": null, "status": "draft", "id": "c77924ab-61e5-52d0-a54d-2fdd6af97658"}, {"name": "刘处让", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘处让。", "biography": null, "status": "draft", "id": "7607f037-c9b6-5f79-b064-81fcfd4ee40d"}, {"name": "范守图", "aliases": ["范守圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的儿子。938年九月乙巳，杨光远将他和范守英送往大梁。生卒年和兄弟长幼未载。", "biography": null, "status": "draft", "id": "d68b8005-9b2c-5627-acd8-9a0d40cc666a"}, {"name": "范守英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的儿子。938年九月乙巳，杨光远将他和范守图送往大梁。生卒年和兄弟长幼未载。", "biography": null, "status": "draft", "id": "be252287-2af8-5e4d-bade-9c6ac5292b84"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
