8, "time_original": "《辽史》会同元年十一月丙寅（938）", "dynasty": "五代十国", "description": "《辽史》记载，耶律德光在宣政殿接受册礼，刘昫、卢重为他册上“睿文神武法天启运明德章信至道广敬昭孝嗣圣皇帝”的尊号。", "phases": [], "location_name": "宣政殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5c08d9e2-2829-5904-bfa4-152721c6244e"}, {"title": "石敬瑭对契丹采用称臣和父皇帝等外交礼节", "start_year": null, "end_year": null, "time_original": "石敬瑭在位期间的交往追述，具体起止日期未载", "dynasty": "五代十国", "description": "石敬瑭谨慎对待契丹，上表称臣，称耶律德光为“父皇帝”；契丹使者到来时，他在别殿拜受诏敕。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "63e34c1e-cc4f-5d1f-ad51-182a4934aed7"}, {"title": "后晋除每年输送金帛外，还向契丹君臣赠送礼物", "start_year": null, "end_year": null, "time_original": "石敬瑭在位期间的交往追述，具体起止日期未载", "dynasty": "五代十国", "description": "后晋除每年输送金帛三十万外，还在庆吊和岁时往来中赠送珍异物品。受赠者包括契丹太后、元帅太子、伟王、南北二王、韩延徽和赵延寿等人。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "78e5a295-b40b-5775-99c5-f11a669c03ce"}, {"title": "石敬瑭以谦卑言辞回应契丹责让", "start_year": null, "end_year": null, "time_original": "石敬瑭在位期间的交往追述，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭以谦卑言辞回应契丹责让。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3cdc34f5-95fc-5e08-b059-849f2f385178"}, {"title": "后晋使者报告在契丹遭遇不逊言辞，朝野以为耻辱", "start_year": null, "end_year": null, "time_original": "石敬瑭在位期间的交往追述", "dynasty": "五代十国", "description": "后晋使者报告契丹方面态度骄倨、言辞不逊，朝野认为耻辱。史书接着概述石敬瑭始终谨慎对待契丹，两国在他在位期间没有发生决裂。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "lo